@app.get("/orders")
def list_orders(db: Session = Depends(get_db)):
    orders = db.scalars(select(Order)).all()          # 50 orders
    return [{"id": o.id, "customer": o.customer.name} for o in orders]

# Order.customer = relationship(Customer)  (default lazy loading)

@app.post("/customers")
def create_customer(data: CustomerIn, db: Session = Depends(get_db)):
    customer = Customer(name=data.name)
    db.add(customer)
    db.flush()                  # assigns customer.id
    return {"id": customer.id}

# get_db closes the session after the request; nothing else commits.

@app.get("/users/by-email")
def by_email(email: str, db: Session = Depends(get_db)):
    user = db.scalars(select(User).where(User.email == email)).first()
    return {"name": user.name}
